Translate the following Java 8 code to GNU C++11 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original Java 8 code you have to translate:
<original_code>
import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter writer = new PrintWriter(System.out);
        int n = Integer.parseInt(reader.readLine().trim());
        String line = reader.readLine();

        String regex = "\\([\\w_]*\\)";
        String[] segments = line.split(regex);
        int maxWordLength = 0;
        for (String segment : segments) {
            int currentMax = Arrays.stream(segment.split("_"))
                                   .mapToInt(String::length)
                                   .max()
                                   .orElse(0);
            if (currentMax > maxWordLength) {
                maxWordLength = currentMax;
            }
        }

        Pattern pattern = Pattern.compile(regex);
        Matcher matcher = pattern.matcher(line);
        long totalInsideWords = 0;
        while (matcher.find()) {
            String inside = matcher.group().substring(1, matcher.group().length() - 1);
            totalInsideWords += Arrays.stream(inside.split("_"))
                                      .filter(s -> !s.isEmpty())
                                      .count();
        }
        writer.println(maxWordLength + " " + totalInsideWords);
        writer.close();
    }
}
